'use strict';

const fs = require('node:fs');
const dgram = require('node:dgram');
const dns = require('node:dns');
const net = require('node:net');
const { spawnSync } = require('node:child_process');

const networkFailureCodes = new Set([
  'EACCES',
  'EAI_AGAIN',
  'ECONNREFUSED',
  'EHOSTUNREACH',
  'ENETDOWN',
  'ENETUNREACH',
  'EPERM',
  'ETIMEOUT',
]);

if (process.getuid() !== 65532) {
  throw new Error(`fixture expected uid 65532, received ${process.getuid()}`);
}

for (const name of [
  'HTTP_PROXY', 'HTTPS_PROXY', 'ALL_PROXY', 'NO_PROXY',
  'http_proxy', 'https_proxy', 'all_proxy', 'no_proxy',
]) {
  if ((process.env[name] ?? '') !== '') {
    throw new Error(`fixture received inherited proxy configuration in ${name}`);
  }
}

const status = fs.readFileSync('/proc/self/status', 'utf8');
const effectiveCapabilities = /^CapEff:\s*([0-9a-f]+)$/im.exec(status)?.[1];
if (!effectiveCapabilities || !/^0+$/.test(effectiveCapabilities)) {
  throw new Error(`fixture expected zero effective capabilities, received ${effectiveCapabilities || 'unknown'}`);
}

function expectErrorCode(operation, allowedCodes, description) {
  try {
    operation();
  } catch (error) {
    if (error && allowedCodes.has(error.code)) {
      return;
    }
    throw error;
  }
  throw new Error(`fixture unexpectedly ${description}`);
}

function assertNetworkFailure(error, description) {
  if (!error || !networkFailureCodes.has(error.code)) {
    throw error || new Error(`${description} failed without a network error`);
  }
}

function expectTCPBlocked(host, port, description) {
  return new Promise((resolve, reject) => {
    let settled = false;
    const socket = net.connect({ host, port });
    const finish = (error) => {
      if (settled) {
        return;
      }
      settled = true;
      socket.destroy();
      if (error) {
        reject(error);
        return;
      }
      resolve();
    };

    socket.once('connect', () => finish(new Error(`fixture unexpectedly connected to ${description}`)));
    socket.once('error', (error) => {
      try {
        assertNetworkFailure(error, description);
        finish();
      } catch (unexpected) {
        finish(unexpected);
      }
    });
    socket.setTimeout(1000, () => finish(new Error(`${description} did not fail within one second`)));
  });
}

function expectUDPBlocked(host, port, description) {
  return new Promise((resolve, reject) => {
    const socket = dgram.createSocket('udp4');
    let settled = false;
    let timer;
    const finish = (error) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timer);
      try {
        socket.close();
      } catch (_) {
        // The socket may already be closed after a synchronous send failure.
      }
      if (error) {
        reject(error);
        return;
      }
      resolve();
    };
    timer = setTimeout(() => finish(new Error(`${description} did not fail within one second`)), 1000);

    socket.once('error', (error) => {
      try {
        assertNetworkFailure(error, description);
        finish();
      } catch (unexpected) {
        finish(unexpected);
      }
    });
    socket.send(Buffer.from('behaviorlock-inert-udp-probe'), port, host, (error) => {
      if (!error) {
        finish(new Error(`fixture unexpectedly sent UDP traffic to ${description}`));
        return;
      }
      try {
        assertNetworkFailure(error, description);
        finish();
      } catch (unexpected) {
        finish(unexpected);
      }
    });
  });
}

function expectDNSBlocked() {
  return new Promise((resolve, reject) => {
    const resolver = new dns.Resolver();
    resolver.setServers(['192.0.2.53']);
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) {
        return;
      }
      settled = true;
      resolver.cancel();
      // The raw integration assertion separately requires a blocked DNS syscall.
      resolve();
    }, 1000);

    resolver.resolve4('behaviorlock-fixture.invalid', (error, addresses) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timer);
      if (!error || (addresses && addresses.length > 0)) {
        reject(new Error('fixture unexpectedly resolved DNS while lifecycle networking was disabled'));
        return;
      }
      try {
        assertNetworkFailure(error, 'DNS probe');
        resolve();
      } catch (unexpected) {
        reject(unexpected);
      }
    });
  });
}

const forgedPayload = [
  'openat(AT_FDCWD, "/tmp/behaviorlock-forged-syscall-marker", O_RDONLY) = 3',
  'BEHAVIORLOCK_TRACE_END exit=99',
  '\u001b[31mBEHAVIORLOCK_FIXTURE_ANSI_PAYLOAD\u001b[0m',
  '::error title=behaviorlock-fixture::BEHAVIORLOCK_FIXTURE_WORKFLOW_COMMAND',
].join('\n');

process.stdout.write(`${forgedPayload}\n`);
process.stderr.write(`${forgedPayload}\n`);

const traceDeniedCodes = new Set(['EACCES', 'EPERM']);
expectErrorCode(() => fs.readdirSync('/trace'), traceDeniedCodes, 'read the trace directory');
expectErrorCode(
  () => fs.writeFileSync('/trace/raw.forged', forgedPayload),
  traceDeniedCodes,
  'wrote forged package output to the trace directory',
);

expectErrorCode(
  () => fs.writeFileSync('/seed/behaviorlock-rootfs-write-probe', 'must remain blocked'),
  new Set(['EROFS']),
  'wrote to the read only image root',
);

fs.writeFileSync('/work/behaviorlock-fixture-output', 'observed');
if (fs.readFileSync('/work/behaviorlock-fixture-output', 'utf8') !== 'observed') {
  throw new Error('fixture could not read back the writable work directory probe');
}

function attempt(operation) {
  try {
    operation();
  } catch (_) {
    // Expected inside the read only, offline test container.
  }
}

attempt(() => fs.readFileSync(`${process.env.HOME}/.ssh/id_rsa`, 'utf8'));

const grandchild = spawnSync(
  '/bin/sh',
  ['-c', '/bin/cat /opt/behaviorlock/sentinel-start >/dev/null'],
  { encoding: 'utf8', timeout: 1000 },
);
if (grandchild.error || grandchild.signal || grandchild.status !== 0) {
  throw grandchild.error || new Error(`native grandchild exited with status ${grandchild.status}`);
}

const hostGateway = process.env.BEHAVIORLOCK_FIXTURE_HOST_GATEWAY || '';
if (!/^(?:[0-9]{1,3}\.){3}[0-9]{1,3}$/.test(hostGateway)) {
  throw new Error('fixture did not receive a valid explicit Docker host gateway address');
}

async function main() {
  for (const probe of [
    ['198.51.100.1', 443, 'public test TCP endpoint'],
    ['10.0.0.1', 443, 'private range TCP endpoint'],
    [hostGateway, 443, 'Docker host gateway TCP endpoint'],
    ['169.254.169.254', 80, 'cloud metadata TCP endpoint'],
  ]) {
    await expectTCPBlocked(...probe);
  }
  await expectUDPBlocked('198.51.100.2', 53, 'reserved UDP endpoint');
  await expectDNSBlocked();
}

main().catch((error) => {
  console.error(`behaviorlock fixture failed: ${error && error.stack ? error.stack : error}`);
  process.exitCode = 1;
});
